import{_ as e,o as l,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const y=JSON.parse('{"title":"💻 前端播放引擎集成 (Jessibuca)","description":"","frontmatter":{},"headers":[],"relativePath":"media/player.md","filePath":"media/player.md"}'),n={name:"media/player.md"};function d(i,t,r,o,g,f){return l(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="💻-前端播放引擎集成-jessibuca" tabindex="-1">💻 前端播放引擎集成 (Jessibuca) <a class="header-anchor" href="#💻-前端播放引擎集成-jessibuca" aria-label="Permalink to &quot;💻 前端播放引擎集成 (Jessibuca)&quot;">​</a></h1><p>在工业安防和数字驾驶舱中，浏览器原生对 RTSP / RTMP 等传统流媒体的支持较差，且公网 HLS 存在数秒以上的高延迟。MzMedia 在前端集成了高性能的 <strong>Jessibuca</strong> 播放器，并配套完整的降级兼容方案。</p><hr><h2 id="_1-播放协议与延迟对比" tabindex="-1">1. 播放协议与延迟对比 <a class="header-anchor" href="#_1-播放协议与延迟对比" aria-label="Permalink to &quot;1. 播放协议与延迟对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">播放协议</th><th style="text-align:left;">传输层</th><th style="text-align:left;">典型延迟</th><th style="text-align:left;">H.264 解码</th><th style="text-align:left;">H.265 (HEVC) 硬解</th><th style="text-align:left;">适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WebRTC</strong></td><td style="text-align:left;">UDP / DTLS</td><td style="text-align:left;"><strong>&lt; 500ms</strong></td><td style="text-align:left;">原生硬件加速</td><td style="text-align:left;">支持（需浏览器/显卡硬解）</td><td style="text-align:left;">实时云台操控、语音对讲、极速响应大屏</td></tr><tr><td style="text-align:left;"><strong>WS-FLV</strong></td><td style="text-align:left;">WebSocket / TCP</td><td style="text-align:left;"><strong>&lt; 1000ms</strong></td><td style="text-align:left;">WASM / Canvas</td><td style="text-align:left;">支持</td><td style="text-align:left;">局域网防火墙阻断 UDP 时的次选低延时方案</td></tr><tr><td style="text-align:left;"><strong>HTTP-FLV</strong></td><td style="text-align:left;">HTTP Chunked</td><td style="text-align:left;"><strong>1 ~ 2 秒</strong></td><td style="text-align:left;">MSE 硬件加速</td><td style="text-align:left;">需特定内核支持</td><td style="text-align:left;">局域网低配置设备、传统浏览器</td></tr><tr><td style="text-align:left;"><strong>HLS (m3u8)</strong></td><td style="text-align:left;">HTTP 切片</td><td style="text-align:left;"><strong>3 ~ 10 秒</strong></td><td style="text-align:left;">原生硬件加速</td><td style="text-align:left;">支持</td><td style="text-align:left;">弱网环境、公网录像历史点播回放</td></tr></tbody></table><hr><h2 id="_2-前端组件化集成示例" tabindex="-1">2. 前端组件化集成示例 <a class="header-anchor" href="#_2-前端组件化集成示例" aria-label="Permalink to &quot;2. 前端组件化集成示例&quot;">​</a></h2><p>在 <code>ui/src/views/media/live/index.vue</code> 中，Jessibuca 播放组件封装了：</p><ul><li><strong>多分屏自由切换</strong>：支持 1分屏、4分屏、9分屏、16分屏自由切换与轮询；</li><li><strong>PTZ 云台十字控制盘</strong>：鼠标按下发送转动信令，松开自动发送停止信令；</li><li><strong>全屏与抓拍</strong>：支持一键将当前关键帧截取为高清 PNG 并存盘；</li><li><strong>本地即时录屏</strong>：支持在前端将实时画面录制为 WebM/MP4 格式下载。</li></ul>',9)])])}const h=e(n,[["render",d]]);export{y as __pageData,h as default};
